from typing import Generator, Iterator, Tuple
from google.cloud import speech_v1 as speech

class GoogleCloudStreamingRecognizer:
    def __init__(self, language_code: str = "en-US", model: str = "phone_call", sample_rate_hertz: int = 16000):
        self.client = speech.SpeechClient()
        self.stream_config = speech.StreamingRecognitionConfig(
            config=speech.RecognitionConfig(
                encoding=speech.RecognitionConfig.AudioEncoding.LINEAR16,
                sample_rate_hertz=sample_rate_hertz,
                language_code=language_code,
                model=model,
            ),
            interim_results=True,
        )

    def process_stream(self, audio_chunks: Generator[bytes, None, None]) -> Iterator[Tuple[bool, str]]:
        def request_iterator():
            yield speech.StreamingRecognizeRequest(streaming_config=self.stream_config)
            for chunk in audio_chunks:
                yield speech.StreamingRecognizeRequest(audio_content=chunk)

        response_stream = self.client.streaming_recognize(requests=request_iterator())

        for response in response_stream:
            if not response.results:
                continue
            for result in response.results:
                transcript = result.alternatives[0].transcript
                is_final = result.is_final
                yield is_final, transcript
